package com.thurdass.system2a.controller;
import com.thurdass.system2a.dto.response.UserResponse; import com.thurdass.system2a.entity.User; import com.thurdass.system2a.exception.ResourceNotFoundException; import com.thurdass.system2a.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController {final UserRepository users;final ActivityRepository activities;final AnnouncementRepository announcements;public AdminController(UserRepository u,ActivityRepository a,AnnouncementRepository n){users=u;activities=a;announcements=n;} @GetMapping("/users") public List<UserResponse> users(){return users.findAll().stream().map(UserResponse::from).toList();} @PatchMapping("/users/{id}/status") public UserResponse status(@PathVariable Long id,@RequestParam boolean enabled){var u=users.findById(id).orElseThrow(()->new ResourceNotFoundException("User not found"));u.setEnabled(enabled);return UserResponse.from(users.save(u));} @GetMapping("/dashboard") public Map<String,Long> dashboard(){return Map.of("users",users.count(),"activeUsers",users.findAll().stream().filter(User::isEnabled).count(),"activities",activities.countByActiveTrue(),"announcements",announcements.countByActiveTrue());}}
